custom_css:
/* 十二时辰·申·白  ·  by if love
   申时 15:00–17:00 ｜ 冷 ｜ 白 —— 挂在电线上的冰封相片
   按 SillyTavern 1.19 源码结构编写 */
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600&display=swap');

/* ========== 1. 色值 ========== */
:root {
  --sb-line: #3f78b8;
  --sb-line-soft: #a9c9e8;
  --sb-sign: #2f78c4;
  --sb-ice: #e6f1fb;
  --sb-ink: #33506a;
  --sb-mute: #7d97ab;
  --sb-quote: #2f6fa8;
  --sb-card: rgba(255, 255, 255, .78);
  --sb-field: rgba(255, 255, 255, .82);
  --sb-tint: rgba(63, 120, 184, .10);
  --sb-tint-2: rgba(63, 120, 184, .18);
  --sb-hero-h: 250px;
  --sb-frame-w: 190px;
  --sb-serif: 'Noto Serif SC', 'Noto Serif CJK SC', 'Songti SC', serif;

  /* 酒馆默认是深色系：把它用来做灰底的半透明黑/白换成冰色，消除灰色残留 */
  --black30a: rgba(255, 255, 255, .62);
  --black50a: rgba(63, 120, 184, .14);
  --black60a: rgba(63, 120, 184, .18);
  --black70a: rgba(230, 241, 251, .94);
  --black90a: rgba(230, 241, 251, .97);
  --white20a: rgba(63, 120, 184, .22);
  --white30a: rgba(63, 120, 184, .14);
  --white50a: rgba(51, 80, 106, .55);
  --white70a: rgba(51, 80, 106, .78);
  --grey30a: rgba(63, 120, 184, .08);
  --grey5020a: rgba(63, 120, 184, .22);
  --grey5050a: rgba(63, 120, 184, .35);
  --grey7070a: rgba(63, 120, 184, .45);
  --interactable-outline-color: var(--sb-line);
}

/* ========== 2. 滚动条外观 ========== */
::-webkit-scrollbar { display: none !important; }
* { scrollbar-width: none !important; -ms-overflow-style: none !important; }

/* ========== 3. 背景 ========== */
#bg1, #bg_custom {
  background-color: var(--sb-ice) !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: 420px 420px !important;
  background-repeat: repeat !important;
  background-position: center top !important;
}

/* ========== 4. 顶栏：雪地小物 ========== */
#top-bar {
  background: rgba(255, 255, 255, .9) !important;
  box-shadow: none !important;
  border: none !important;
}
#top-bar::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -9px;
  height: 12px;
  background: url("data:image/svg+xml;base64,") left top / 60px 12px repeat-x;
  pointer-events: none;
}
/* 只替换图标的绘制层：原图标字形改透明，点击宿主不动 */
#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon {
  color: transparent !important;
  text-shadow: none !important;
  filter: none !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 1.05em 1.05em !important;
  border-radius: 50% !important;
  opacity: .78 !important;
  transition: opacity .2s, transform .2s, background-color .2s;
}
#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon:hover { opacity: 1 !important; }
#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon.openIcon {
  opacity: 1 !important;
  background-color: #dcecfb !important;
  box-shadow: 0 0 0 1.5px var(--sb-line-soft) !important;
  transform: translateY(1px);
}
#leftNavDrawerIcon { background-image: url("data:image/svg+xml;base64,") !important; }
#API-status-top { background-image: url("data:image/svg+xml;base64,") !important; }
#API-status-top.fa-plug-circle-exclamation { background-image: url("data:image/svg+xml;base64,") !important; }
#advanced-formatting-button .drawer-icon { background-image: url("data:image/svg+xml;base64,") !important; }
#WIDrawerIcon { background-image: url("data:image/svg+xml;base64,") !important; }
#user-settings-button .drawer-icon { background-image: url("data:image/svg+xml;base64,") !important; }
#backgrounds-button .drawer-icon { background-image: url("data:image/svg+xml;base64,") !important; }
#extensions-settings-button .drawer-icon { background-image: url("data:image/svg+xml;base64,") !important; }
#persona-management-button .drawer-icon { background-image: url("data:image/svg+xml;base64,") !important; }
#rightNavDrawerIcon { background-image: url("data:image/svg+xml;base64,") !important; }

/* ========== 5. 通用控件（抽屉/弹窗共用） ========== */
textarea, .text_pole, select, input[type="text"], input[type="search"], input[type="number"],
.range-block-counter input, .neo-range-input, .edit_textarea {
  background-color: var(--sb-field) !important;
  color: var(--sb-ink) !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 10px !important;
}
.neo-range-input { border-radius: 0 0 10px 10px !important; }
textarea:focus, .text_pole:focus, select:focus, input:focus-visible {
  border-color: var(--sb-line) !important;
  outline: none !important;
}
::placeholder { color: var(--sb-mute) !important; opacity: 1 !important; }

input[type="checkbox"] {
  background-color: #fff !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  outline: none !important;
  box-shadow: none !important;
  filter: none !important;
  border-radius: 5px !important;
}
input[type="checkbox"]:checked {
  background-color: var(--sb-sign) !important;
  border-color: var(--sb-sign) !important;
}
input[type="checkbox"]::before { box-shadow: inset 1em 1em #fff !important; }

input[type="range"], .neo-range-slider {
  background-color: var(--sb-tint-2) !important;
  background-image: linear-gradient(var(--sb-line-soft), var(--sb-line-soft)) !important;
  box-shadow: none !important;
  filter: none !important;
}
input[type="range"]::-webkit-slider-thumb, .neo-range-slider::-webkit-slider-thumb {
  background: #fff !important;
  border: 2px solid var(--sb-sign) !important;
}
input[type="range"]::-moz-range-thumb, .neo-range-slider::-moz-range-thumb {
  background: #fff !important;
  border: 2px solid var(--sb-sign) !important;
}

.menu_button {
  background-color: rgba(255, 255, 255, .8) !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 10px !important;
  color: var(--sb-line) !important;
  filter: none !important;
}
.menu_button:not(.disabled):not([disabled]):hover,
.menu_button:not(.disabled):not([disabled]).active {
  background-color: var(--sb-ice) !important;
  border-color: var(--sb-line) !important;
}
.menu_button.disabled, .menu_button[disabled] { opacity: .45 !important; }
.menu_button.caution, .menu_button.redWarningBG { color: #c0504d !important; }

/* 抽屉、面板 */
.drawer-content, #left-nav-panel, #right-nav-panel, #floatingPrompt, #cfgConfig {
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 0 0 18px 18px !important;
  box-shadow: none !important;
}
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background: rgba(255, 255, 255, .78) !important;
  background-image: none !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 12px !important;
  color: var(--sb-line) !important;
  box-shadow: none !important;
}
.standoutHeader ~ .inline-drawer-content {
  background-color: rgba(255, 255, 255, .45) !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 12px !important;
}
.inline-drawer-icon, .inline-drawer-toggle .fa-circle-chevron-down { color: var(--sb-line) !important; }
hr, .sysHR { border-color: var(--sb-line-soft) !important; }

/* 预设 / 提示词管理器列表 */
#completion_prompt_manager .completion_prompt_manager_header,
#completion_prompt_manager .completion_prompt_manager_header div { color: var(--sb-mute) !important; }
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background-color: rgba(255, 255, 255, .72) !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 12px !important;
  margin-bottom: 6px !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background-color: rgba(255, 255, 255, .35) !important;
  border: 1px dashed var(--sb-line-soft) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_list_head {
  color: var(--sb-mute) !important;
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span { filter: none !important; color: var(--sb-line) !important; }
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
  filter: none !important;
  opacity: .8 !important;
  color: var(--sb-line);
}
#completion_prompt_manager .prompt-manager-toggle-action { color: var(--sb-sign) !important; opacity: 1 !important; }
#completion_prompt_manager .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action { color: var(--sb-mute) !important; }

/* 标签、选择框插件 */
.tag { border-radius: 8px !important; }
.select2-container .select2-selection, .select2-dropdown {
  background-color: var(--sb-field) !important;
  border: 1px solid var(--sb-line-soft) !important;
  color: var(--sb-ink) !important;
}

/* 弹窗与遮罩 */
.popup, dialog.popup {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 18px !important;
  box-shadow: 0 10px 30px rgba(63, 120, 184, .18) !important;
  color: var(--sb-ink) !important;
}
.list-group, #options .options-content, #extensionsMenu {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 14px !important;
  box-shadow: 0 8px 22px rgba(63, 120, 184, .15) !important;
}
#options .options-content a, #extensionsMenu .list-group-item { color: var(--sb-ink) !important; }
#options .options-content a:hover, #extensionsMenu .list-group-item:hover { background-color: var(--sb-ice) !important; }

/* 通知 */
#toast-container > .toast {
  background-color: rgba(255, 255, 255, .96) !important;
  background-position: 14px center !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 14px !important;
  box-shadow: 0 6px 18px rgba(63, 120, 184, .18) !important;
  color: var(--sb-ink) !important;
  opacity: 1 !important;
}
#toast-container > .toast-success { border-color: #8fc7a8 !important; }
#toast-container > .toast-error { border-color: #e2a3a1 !important; }
#toast-container > .toast-warning { border-color: #e8c98b !important; }
#toast-container > .toast .toast-title { color: var(--sb-line) !important; }
#toast-container > .toast-success::before,
#toast-container > .toast-info::before,
#toast-container > .toast-warning::before,
#toast-container > .toast-error::before { color: var(--sb-line) !important; }

/* ========== 6. 聊天区 ========== */
#chat {
  background: transparent !important;
  padding-inline: 8px !important;
}

#chat .mes[is_system="false"] {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  padding: 22px 4px 30px !important;
  margin: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 楼层分隔：斑马线 */
#chat .mes + .mes[is_system="false"] { padding-top: 60px !important; }
#chat .mes + .mes[is_system="false"]::before {
  content: "";
  position: absolute;
  top: 12px;
  left: 6%;
  width: 88%;
  height: 26px;
  background: url("data:image/webp;base64,") center / contain no-repeat;
  pointer-events: none;
}

/* ----- 卡头 ----- */
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  position: relative !important;
  display: block !important;
  flex: none !important;
  width: 100% !important;
  height: var(--sb-hero-h) !important;
  min-height: var(--sb-hero-h) !important;
  margin: 0 !important;
  border: 1.5px solid var(--sb-line) !important;
  border-radius: 20px !important;
  box-sizing: border-box !important;
  background:
    linear-gradient(90deg, rgba(255,255,255,.9) 0%, rgba(255,255,255,.62) 46%, rgba(255,255,255,0) 72%),
    url("data:image/webp;base64,") center bottom / cover no-repeat !important;
  overflow: visible !important;
}
#chat .mes[is_user="true"] > .mesAvatarWrapper {
  background:
    linear-gradient(270deg, rgba(255,251,248,.94) 0%, rgba(255,251,248,.66) 46%, rgba(255,251,248,.12) 72%),
    url("data:image/webp;base64,") center bottom / cover no-repeat !important;
}

/* 小鱼 */
#chat .mes[is_system="false"] > .mesAvatarWrapper::after {
  content: "";
  position: absolute;
  left: 22px;
  bottom: 54px;
  width: 52px;
  height: 24px;
  background: url("data:image/webp;base64,") center / contain no-repeat;
  pointer-events: none;
}
#chat .mes[is_user="true"] > .mesAvatarWrapper::after {
  left: auto;
  right: 22px;
  transform: scaleX(-1);
}

/* 冰封相片 */
#chat .mes[is_system="false"] .mesAvatarWrapper > .avatar {
  position: absolute !important;
  top: -16px !important;
  right: 12px !important;
  left: auto !important;
  width: var(--sb-frame-w) !important;
  height: calc(var(--sb-frame-w) * 1.1875) !important;
  flex: none !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  outline: none !important;
  overflow: visible !important;
  transform: rotate(3deg);
  z-index: 1;
}
#chat .mes[is_system="false"] .mesAvatarWrapper > .avatar img {
  position: absolute !important;
  left: 20.6% !important;
  top: 20.5% !important;
  width: 60.2% !important;
  height: 61.4% !important;
  max-width: none !important;
  object-fit: cover !important;
  border: none !important;
  border-radius: 8px !important;
  box-shadow: none !important;
  outline: none !important;
}
#chat .mes[is_system="false"] .mesAvatarWrapper > .avatar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: url("data:image/webp;base64,") center / 100% 100% no-repeat;
  pointer-events: none;
}
#chat .mes[is_user="true"] .mesAvatarWrapper > .avatar {
  right: auto !important;
  left: 12px !important;
  height: calc(var(--sb-frame-w) * 1.202) !important;
  transform: rotate(-3deg);
}
#chat .mes[is_user="true"] .mesAvatarWrapper > .avatar img {
  left: 18.6% !important;
  top: 23.3% !important;
  width: 62.6% !important;
  height: 61.6% !important;
}
#chat .mes[is_user="true"] .mesAvatarWrapper > .avatar::after { background-image: url("data:image/webp;base64,"); }

/* 统计条：楼层 / 用时 / token —— 在卡头底部排成一行，空的不显示 */
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  display: flex !important;
  flex-direction: row !important;
  align-items: flex-end !important;
  justify-content: flex-start !important;
  gap: 6px !important;
  padding: 0 18px 14px !important;
}
#chat .mes[is_user="true"] > .mesAvatarWrapper { justify-content: flex-end !important; }
#chat .mes[is_system="false"] .mesAvatarWrapper > .mesIDDisplay,
#chat .mes[is_system="false"] .mesAvatarWrapper > .mes_timer,
#chat .mes[is_system="false"] .mesAvatarWrapper > .tokenCounterDisplay {
  position: static !important;
  flex: none !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 3px 9px !important;
  text-align: center !important;
  font: 600 11px/1.3 system-ui, sans-serif !important;
  color: var(--sb-line) !important;
  background: rgba(255,255,255,.92) !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 10px !important;
  opacity: 1 !important;
  white-space: nowrap !important;
}
#chat .mes[is_system="false"] .mesAvatarWrapper > .mesIDDisplay:empty,
#chat .mes[is_system="false"] .mesAvatarWrapper > .mes_timer:empty,
#chat .mes[is_system="false"] .mesAvatarWrapper > .tokenCounterDisplay:empty { display: none !important; }

/* ----- 名牌 / 时间 / 按钮：放进卡头信息栏 ----- */
#chat .mes[is_system="false"] > .mes_block {
  position: static !important;
  width: 100% !important;
  min-width: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
}
#chat .mes[is_system="false"] .mes_block > .ch_name {
  position: absolute !important;
  top: 46px !important;
  left: 20px !important;
  right: auto !important;
  width: calc(100% - var(--sb-frame-w) - 52px) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 8px !important;
  z-index: 2;
}
#chat .mes + .mes[is_system="false"] .mes_block > .ch_name { top: 84px !important; }
#chat .mes[is_user="true"] .mes_block > .ch_name {
  left: auto !important;
  right: 20px !important;
  align-items: flex-end !important;
}
#chat .mes[is_system="false"] .ch_name > .flex-container:first-child,
#chat .mes[is_system="false"] .ch_name .alignItemsBaseline {
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 6px !important;
  width: 100% !important;
  flex: none !important;
}
#chat .mes[is_user="true"] .ch_name > .flex-container:first-child,
#chat .mes[is_user="true"] .ch_name .alignItemsBaseline { align-items: flex-end !important; }

#chat .mes[is_system="false"] .ch_name .name_text {
  display: block !important;
  box-sizing: border-box !important;
  width: 164px !important;
  max-width: 100% !important;
  height: 43px !important;
  padding: 20px 34px 0 16px !important;
  background: url("data:image/webp;base64,") center / 100% 100% no-repeat !important;
  color: #1f4f82 !important;
  font: 700 13px/16px system-ui, sans-serif !important;
  letter-spacing: .06em !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  text-shadow: 0 1px 0 rgba(255,255,255,.75) !important;
}
#chat .mes[is_user="true"] .ch_name .name_text {
  padding: 20px 14px 0 44px !important;
  text-align: right !important;
  background-image: url("data:image/webp;base64,") !important;
}
#chat .mes[is_system="false"] .ch_name .timestamp {
  margin: 0 !important;
  padding: 1px 8px !important;
  font: 11px/1.5 system-ui, sans-serif !important;
  color: var(--sb-mute) !important;
  background: rgba(255,255,255,.85) !important;
  border-radius: 8px !important;
  max-width: 100% !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
#chat .mes[is_system="false"] .ch_name .mes_ghost { color: var(--sb-mute) !important; }

/* 消息按钮：白色小圆钮 */
#chat .mes[is_system="false"] .ch_name .mes_buttons,
#chat .mes[is_system="false"] .ch_name .mes_edit_buttons {
  flex-wrap: wrap !important;
  gap: 6px !important;
  max-width: 100% !important;
}
#chat .mes[is_user="true"] .ch_name .mes_buttons { justify-content: flex-end !important; }
#chat .mes[is_system="false"] .ch_name .mes_buttons .mes_button {
  width: 26px !important;
  height: 26px !important;
  padding: 0 !important;
  box-sizing: border-box !important;
  line-height: 23px !important;
  text-align: center !important;
  font-size: 12px !important;
  color: var(--sb-line) !important;
  background: rgba(255,255,255,.9) !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 50% !important;
  opacity: 1 !important;
  filter: none !important;
}
#chat .mes[is_system="false"] .ch_name .extraMesButtons { gap: 6px !important; flex-wrap: wrap !important; }

/* ----- 思考块 ----- */
#chat .mes[is_system="false"] .mes_reasoning_details {
  margin-top: 14px !important;
  background: rgba(255,255,255,.6) !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 14px !important;
  padding: 4px 10px !important;
}
#chat .mes .mes_reasoning_summary, #chat .mes .mes_reasoning_header_title { color: var(--sb-mute) !important; }

/* ----- 正文卡片 ----- */
#chat .mes[is_system="false"] .mes_text {
  position: relative !important;
  margin-top: 16px !important;
  padding: 14px 16px !important;
  background: var(--sb-card) !important;
  border: 1.5px solid var(--sb-line-soft) !important;
  border-radius: 16px !important;
  color: var(--sb-ink) !important;
  font-family: var(--sb-serif) !important;
  font-size: calc(var(--mainFontSize) * 1.02) !important;
  line-height: 1.95 !important;
  box-sizing: border-box !important;
}
#chat .mes[is_user="true"] .mes_text { background: rgba(255,251,248,.86) !important; }
#chat .mes[is_system="false"] .mes_text::after {
  content: "";
  position: absolute;
  top: -15px;
  right: -6px;
  width: 32px;
  height: 32px;
  background: url("data:image/webp;base64,") center / contain no-repeat;
  transform: rotate(-12deg);
  pointer-events: none;
}
#chat .mes[is_user="true"] .mes_text::after { right: auto; left: -6px; transform: rotate(14deg); }
#chat .mes .mes_text q { color: var(--sb-quote) !important; }
#chat .mes .mes_text em, #chat .mes .mes_text i { color: var(--sb-mute) !important; font-style: normal !important; }
#chat .mes .mes_text strong, #chat .mes .mes_text b { color: var(--sb-line) !important; }
#chat .mes .mes_text u { text-decoration-color: var(--sb-line-soft) !important; }
#chat .mes .mes_text blockquote, #chat .mes .mes_reasoning blockquote {
  margin: 8px 0 !important;
  padding: 6px 12px !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 12px !important;
  background: rgba(230,241,251,.7) !important;
}
#chat .mes .mes_text code {
  background: var(--sb-ice) !important;
  color: var(--sb-quote) !important;
  border: 1px solid var(--sb-line-soft) !important;
  border-radius: 6px !important;
}
#chat .mes .mes_text pre { border-radius: 12px !important; border: 1px solid var(--sb-line-soft) !important; }
#chat .mes .mes_text hr {
  border: none !important;
  height: 16px !important;
  background: url("data:image/webp;base64,") center / contain no-repeat !important;
}
#chat .mes .edit_textarea {
  margin-top: 16px !important;
  border-radius: 16px !important;
  font-family: var(--sb-serif) !important;
}

/* 翻页 */
#chat .mes .swipe_left, #chat .mes .swipe_right { color: var(--sb-line) !important; opacity: .8; }
#chat .mes .swipes-counter { color: var(--sb-mute) !important; }

/* 系统消息 */
#chat .mes[is_system="true"] .mes_text {
  background: rgba(255,255,255,.7) !important;
  border: 1px dashed var(--sb-line-soft) !important;
  border-radius: 14px !important;
  padding: 10px 14px !important;
  color: var(--sb-ink) !important;
}

/* ========== 7. 输入栏 ========== */
#send_form {
  background: rgba(255,255,255,.9) !important;
  border: 1.5px solid var(--sb-line) !important;
  border-radius: 22px !important;
  box-shadow: none !important;
}
#send_form.no-connection { border-color: var(--sb-line-soft) !important; }
#send_textarea {
  background: transparent !important;
  border: none !important;
  color: var(--sb-ink) !important;
  font-family: var(--sb-serif) !important;
}
#leftSendForm > div, #rightSendForm > div, #send_but, #mes_stop, #options_button, #extensionsMenuButton {
  color: var(--sb-line) !important;
}
#send_but { color: var(--sb-sign) !important; }

/* ========== 8. 手机 ========== */
@media (max-width: 1000px) {
  :root {
    --sb-hero-h: 214px;
    --sb-frame-w: 156px;
  }
  #chat .mes[is_system="false"] .ch_name .name_text {
    width: 146px !important;
    height: 38px !important;
    padding-top: 17px !important;
    font-size: 12px !important;
  }
  #chat .mes[is_user="true"] .ch_name .name_text { padding-left: 38px !important; }
  #chat .mes[is_system="false"] .mes_block > .ch_name { top: 40px !important; }
  #chat .mes + .mes[is_system="false"] .mes_block > .ch_name { top: 78px !important; }
  #chat .mes[is_system="false"] > .mesAvatarWrapper::after { bottom: 46px; width: 46px; }
  #chat .mes[is_system="false"] .ch_name .mes_buttons .mes_button { width: 24px !important; height: 24px !important; font-size: 11px !important; }
}
